import java.io.*
import java.net.URLDecoder
import java.nio.file.*
import java.security.MessageDigest
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec
import java.util.concurrent.ConcurrentHashMap

object SecureFileServer {
    private val UPLOAD_DIR = "/var/data/uploads"
    private val PUBLIC_DIR = "/var/data/public"
    private val ALLOWED_EXTENSIONS = setOf("txt", "csv", "json", "xml")
    private val MAX_PATH_DEPTH = 5
    private val sessions = ConcurrentHashMap<String, UserSession>()

    data class UserSession(
        val userId: String,
        val role: String,
        val homeDir: String,
        val permissions: Set<String>
    )

    fun createSession(userId: String, role: String): String {
        val sessionId = generateSessionId()
        val homeDir = when (role) {
            "admin" -> UPLOAD_DIR
            "user" -> "$UPLOAD_DIR/users/$userId"
            else -> "$PUBLIC_DIR/guest"
        }
        sessions[sessionId] = UserSession(userId, role, homeDir, getPermissions(role))
        return sessionId
    }

    private fun getPermissions(role: String): Set<String> = when (role) {
        "admin" -> setOf("read", "write", "delete", "admin")
        "user" -> setOf("read", "write")
        else -> setOf("read")
    }

    private fun generateSessionId(): String {
        val bytes = ByteArray(32)
        java.security.SecureRandom().nextBytes(bytes)
        return bytes.joinToString("") { "%02x".format(it) }
    }

    /**
     * Resolves a user-provided path safely within their allowed directory.
     * Performs multiple layers of validation to prevent path traversal.
     */
    fun resolvePath(sessionId: String, requestedPath: String): Path? {
        val session = sessions[sessionId] ?: return null

        // Step 1: Reject obviously malicious input
        if (requestedPath.contains("\\0") || requestedPath.length > 4096) {
            return null
        }

        // Step 2: Decode URL encoding to handle encoded traversal attempts
        val decodedPath = decodePathSafely(requestedPath) ?: return null

        // Step 3: Check for traversal sequences after decoding
        if (containsTraversal(decodedPath)) {
            return null
        }

        // Step 4: Validate path depth
        val segments = decodedPath.split("/").filter { it.isNotEmpty() }
        if (segments.size > MAX_PATH_DEPTH) {
            return null
        }

        // Step 5: Validate each segment
        for (segment in segments) {
            if (!isValidSegment(segment)) {
                return null
            }
        }

        // Step 6: Resolve against home directory and verify containment
        val basePath = Paths.get(session.homeDir).toAbsolutePath().normalize()
        val resolvedPath = basePath.resolve(decodedPath).normalize()

        // Step 7: Verify the resolved path is within bounds
        if (!resolvedPath.startsWith(basePath)) {
            return null
        }

        return resolvedPath
    }

    /**
     * Safely decodes URL-encoded path components.
     * Applies decoding iteratively until stable to catch double-encoding.
     */
    private fun decodePathSafely(path: String): String? {
        var current = path
        var previous: String
        var iterations = 0
        val maxIterations = 3

        do {
            previous = current
            current = try {
                URLDecoder.decode(current, "UTF-8")
            } catch (e: Exception) {
                return null
            }
            iterations++
            if (iterations > maxIterations) {
                // Too many encoding layers - suspicious
                return null
            }
        } while (current != previous)

        return current
    }

    private fun containsTraversal(path: String): Boolean {
        val normalized = path.replace("\\", "/")
        return normalized.contains("../") ||
               normalized.contains("/..")||
               normalized == ".." ||
               normalized.startsWith("..")
    }

    private fun isValidSegment(segment: String): Boolean {
        if (segment.isEmpty() || segment.length > 255) return false
        if (segment == "." || segment == "..") return false
        // Allow alphanumeric, dots, hyphens, underscores
        return segment.all { it.isLetterOrDigit() || it in "._-" }
    }

    /**
     * Read a file with permission checking.
     */
    fun readFile(sessionId: String, requestedPath: String): ByteArray? {
        val session = sessions[sessionId] ?: return null
        if ("read" !in session.permissions) return null

        val resolvedPath = resolvePath(sessionId, requestedPath) ?: return null
        val file = resolvedPath.toFile()

        if (!file.exists() || !file.isFile) return null

        // Check file extension
        val ext = file.extension.lowercase()
        if (ext !in ALLOWED_EXTENSIONS) return null

        return file.readBytes()
    }

    /**
     * Write a file with permission checking and content validation.
     */
    fun writeFile(sessionId: String, requestedPath: String, content: ByteArray): Boolean {
        val session = sessions[sessionId] ?: return false
        if ("write" !in session.permissions) return false
        if (content.size > 10 * 1024 * 1024) return false // 10MB limit

        val resolvedPath = resolvePath(sessionId, requestedPath) ?: return false

        // Check file extension
        val ext = resolvedPath.toFile().extension.lowercase()
        if (ext !in ALLOWED_EXTENSIONS) return false

        // Ensure parent directory exists within bounds
        val parentDir = resolvedPath.parent
        val basePath = Paths.get(session.homeDir).toAbsolutePath().normalize()
        if (!parentDir.startsWith(basePath)) return false

        Files.createDirectories(parentDir)
        Files.write(resolvedPath, content)
        return true
    }

    /**
     * Delete a file with permission checking.
     */
    fun deleteFile(sessionId: String, requestedPath: String): Boolean {
        val session = sessions[sessionId] ?: return false
        if ("delete" !in session.permissions) return false

        val resolvedPath = resolvePath(sessionId, requestedPath) ?: return false
        val file = resolvedPath.toFile()

        if (!file.exists() || !file.isFile) return false

        val ext = file.extension.lowercase()
        if (ext !in ALLOWED_EXTENSIONS) return false

        return file.delete()
    }

    /**
     * List files in a directory with permission checking.
     * Supports a 'filter' parameter for searching.
     */
    fun listFiles(sessionId: String, requestedPath: String, filter: String? = null): List<String>? {
        val session = sessions[sessionId] ?: return null
        if ("read" !in session.permissions) return null

        val resolvedPath = resolvePath(sessionId, requestedPath) ?: return null
        val dir = resolvedPath.toFile()

        if (!dir.exists() || !dir.isDirectory) return null

        val files = dir.listFiles() ?: return emptyList()

        return files
            .filter { it.isFile }
            .filter { it.extension.lowercase() in ALLOWED_EXTENSIONS }
            .filter { filter == null || it.name.contains(filter) }
            .map { it.name }
            .sorted()
    }

    /**
     * Admin function to access any path within the upload directory.
     * Uses a separate validation path for admin operations.
     */
    fun adminAccess(sessionId: String, absolutePath: String): ByteArray? {
        val session = sessions[sessionId] ?: return null
        if ("admin" !in session.permissions) return null

        // Admin can access anything under UPLOAD_DIR
        val basePath = Paths.get(UPLOAD_DIR).toAbsolutePath().normalize()
        val targetPath = Paths.get(absolutePath).toAbsolutePath().normalize()

        if (!targetPath.startsWith(basePath)) return null

        val file = targetPath.toFile()
        if (!file.exists() || !file.isFile) return null

        return file.readBytes()
    }

    /**
     * Generates a shareable link token for a file.
     * The token encodes the file path so others can access it.
     */
    fun generateShareToken(sessionId: String, requestedPath: String): String? {
        val session = sessions[sessionId] ?: return null
        if ("read" !in session.permissions) return null

        val resolvedPath = resolvePath(sessionId, requestedPath) ?: return null
        if (!resolvedPath.toFile().exists()) return null

        // Encode path relative to UPLOAD_DIR for sharing
        val basePath = Paths.get(UPLOAD_DIR).toAbsolutePath().normalize()
        val relativePath = basePath.relativize(resolvedPath).toString()

        val timestamp = System.currentTimeMillis()
        val payload = "$relativePath|$timestamp"
        val signature = hmacSign(payload)

        // Token format: base64(payload)|signature
        return java.util.Base64.getUrlEncoder().encodeToString(payload.toByteArray()) + "." + signature
    }

    /**
     * Access a file via share token. Anyone with a valid token can read the file.
     */
    fun accessSharedFile(token: String): ByteArray? {
        val parts = token.split(".")
        if (parts.size != 2) return null

        val payload = try {
            String(java.util.Base64.getUrlDecoder().decode(parts[0]))
        } catch (e: Exception) {
            return null
        }

        val expectedSignature = hmacSign(payload)
        if (!MessageDigest.isEqual(expectedSignature.toByteArray(), parts[1].toByteArray())) {
            return null
        }

        val payloadParts = payload.split("|")
        if (payloadParts.size != 2) return null

        val relativePath = payloadParts[0]
        val timestamp = payloadParts[1].toLongOrNull() ?: return null

        // Token expires after 24 hours
        if (System.currentTimeMillis() - timestamp > 86400000L) return null

        // Resolve the shared path against UPLOAD_DIR
        val basePath = Paths.get(UPLOAD_DIR).toAbsolutePath().normalize()
        val targetPath = basePath.resolve(relativePath).normalize()

        if (!targetPath.startsWith(basePath)) return null

        val file = targetPath.toFile()
        if (!file.exists() || !file.isFile) return null

        return file.readBytes()
    }

    private val HMAC_KEY = SecretKeySpec(
        System.getenv("HMAC_SECRET")?.toByteArray() ?: "default-dev-key-change-in-prod".toByteArray(),
        "HmacSHA256"
    )

    private fun hmacSign(data: String): String {
        val mac = Mac.getInstance("HmacSHA256")
        mac.init(HMAC_KEY)
        return mac.doFinal(data.toByteArray()).joinToString("") { "%02x".format(it) }
    }
}
